async () => {
            if (announcementTitle.trim().length < 3 || announcementBody.trim().length < 3) { setAdminNotice("Enter an announcement title and message."); return; }
            const days = announcementDays.trim() ? Number(announcementDays) : null;
            if (days !== null && (!Number.isInteger(days) || days < 1 || days > 365)) { setAdminNotice("Active days must be a whole number from 1 to 365."); return; }
            const payload = { title: announcementTitle.trim(), body: announcementBody.trim(), audience: announcementAudience, expires_at: days ? new Date(Date.now() + days * 86400000).toISOString() : null };
            try {
              if (editingAnnouncement) await api.patch(`/admin/announcements/${editingAnnouncement}`, payload);
              else await api.post("/admin/announcements", { ...payload, active: true });
              setAdminNotice(editingAnnouncement ? "Announcement updated." : "Announcement published.");
              setEditingAnnouncement(null); setAnnouncementTitle(""); setAnnouncementBody(""); setAnnouncementDays(""); setAnnouncements(await api.get<any[]>("/admin/announcements"));
            }
            catch (e: any) { setAdminNotice(e?.message || "Could not save announcement."); }
          }
